"""Standalone replay artifact; opening the file needs no server or dependencies."""

import json
from pathlib import Path


def write_html(path: Path, result: dict) -> None:
    payload = json.dumps(result, separators=(",", ":")).replace("<", "\\u003c")
    path.write_text(_TEMPLATE.replace("__PAYLOAD__", payload), encoding="utf-8")


_TEMPLATE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>TETR.IO RL · Replay</title><style>
:root{color-scheme:dark;--bg:#080c12;--panel:#101722;--line:#233044;--muted:#8796aa;--ink:#edf4fc;--cyan:#56e1d8}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 65% 0%,#122839 0%,var(--bg) 65%);color:var(--ink);font:15px/1.5 system-ui,sans-serif;min-height:100vh}
main{max-width:1100px;margin:auto;padding:40px 28px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.eyebrow{font:11px monospace;letter-spacing:3px;color:var(--cyan)}h1{font-size:28px;letter-spacing:-1px;margin:5px 0}p{color:var(--muted);margin:4px 0}.badge{border:1px solid #31554f;border-radius:20px;padding:6px 12px;color:var(--cyan);font:12px monospace}
.layout{display:grid;grid-template-columns: minmax(350px,1.1fr) 1fr;gap:24px}.panel{background:#101722dd;border:1px solid var(--line);border-radius:14px;padding:24px}.arena{display:flex;justify-content:center;gap:20px}.side{width:70px;padding-top:8px}.label{font-size:10px;text-transform:uppercase;letter-spacing:2px;color:var(--muted);margin-bottom:12px}canvas#board{width:260px;height:520px;background:#070b10;border:1px solid #31445b;box-shadow:0 16px 45px #0006;max-width:65%}.mini{width:70px;height:52px;display:block}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:18px}.metric strong{display:block;font-size:38px;line-height:1.2;font-weight:600;font-variant-numeric:tabular-nums}.metric span{color:var(--muted);font-size:12px}.section{margin-top:30px;border-top:1px solid var(--line);padding-top:20px}#graph{width:100%;height:135px}.controls{margin-top:24px;display:flex;gap:10px;align-items:center}button,select{background:#1b2939;border:1px solid #33455c;border-radius:7px;color:var(--ink);padding:9px 14px;font:inherit;cursor:pointer}button.primary{background:var(--cyan);border-color:var(--cyan);color:#06201e;font-weight:600}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}input[type=range]{accent-color:var(--cyan);width:100%;margin-top:20px}#position{margin-left:auto;font:12px monospace;color:var(--muted)}#keys{font:12px/1.8 monospace;color:#b9c9dd;overflow-wrap:anywhere;min-height:48px}footer{font-size:12px;color:var(--muted);margin-top:22px}.status{color:var(--cyan);font:12px monospace;margin-top:14px}.hint{font-size:12px} @media(max-width:800px){main{padding:22px 16px}.layout{grid-template-columns:1fr}.panel{padding:18px}.badge{display:none}canvas#board{width:240px;height:480px}}
</style></head><body><main>
<header><div><div class="eyebrow">TETR.IO / REINFORCEMENT LEARNING</div><h1>Watch the agent think ahead.</h1><p>Local placement replay · every move, one board at a time</p></div><span class="badge" id="policy"></span></header>
<div class="layout"><section class="panel" aria-label="Replay board"><div class="arena"><div class="side"><div class="label">Hold</div><canvas class="mini" id="hold" width="140" height="104"></canvas></div><canvas id="board" width="520" height="1040" aria-label="Ten column game board"></canvas><div class="side"><div class="label">Next</div><canvas id="next" width="140" height="600" style="width:70px;height:300px"></canvas></div></div>
<div class="controls"><button class="primary" id="play" aria-label="Play or pause replay">Play</button><button id="back" aria-label="Previous move">←</button><button id="forward" aria-label="Next move">→</button><select id="speed" aria-label="Playback speed"><option value="500">2 pps</option><option value="200" selected>5 pps</option><option value="100">10 pps</option><option value="40">25 pps</option></select><span id="position"></span></div><input id="scrub" type="range" min="0" value="0" aria-label="Replay position"></section>
<aside class="panel"><div class="label">Session / <span id="seed"></span></div><div class="metrics"><div class="metric"><strong id="lines">0</strong><span>lines cleared</span></div><div class="metric"><strong id="pieces">0</strong><span>pieces placed</span></div><div class="metric"><strong id="efficiency">0.00</strong><span>lines / piece</span></div><div class="metric"><strong id="height">0</strong><span>stack height</span></div></div>
<div class="section"><div class="label">Line clears over the episode</div><canvas id="graph" width="700" height="240" aria-label="Cumulative line clear chart"></canvas></div><div class="section"><div class="label">Last move</div><div id="keys">Ready to begin.</div><div class="status" id="status">Episode ready</div></div><div class="section"><p class="hint">Space to play or pause. Arrow keys to step through moves. Drag the timeline to inspect a placement.</p></div></aside></div><footer>Independent research project. Local simulation; not affiliated with TETR.IO. Placement timing is for playback only.</footer>
</main><script>
const data=__PAYLOAD__;
const $=id=>document.getElementById(id), frames=data.frames, colors=['','#52ddeb','#6b8cff','#f6b45c','#f4db6d','#76d696','#bd8af1','#ef788a','#7891a4'];
const shapes={I:[[0,1],[1,1],[2,1],[3,1]],J:[[0,0],[0,1],[1,1],[2,1]],L:[[2,0],[0,1],[1,1],[2,1]],O:[[1,0],[2,0],[1,1],[2,1]],S:[[1,0],[2,0],[0,1],[1,1]],T:[[1,0],[0,1],[1,1],[2,1]],Z:[[0,0],[1,0],[1,1],[2,1]]};
let index=0,playing=false,last=0;
function cell(ctx,x,y,size,value){ctx.fillStyle=colors[value];ctx.fillRect(x+1,y+1,size-2,size-2);ctx.fillStyle='#ffffff2b';ctx.fillRect(x+2,y+2,size-4,3)}
function mini(ctx,p,y=0){if(!p)return;const value='IJLOSTZ'.indexOf(p)+1;for(const [x,dy]of shapes[p])cell(ctx,x*30+10,dy*30+y+12,30,value)}
function draw(){const f=frames[index],ctx=$('board').getContext('2d');ctx.clearRect(0,0,520,1040);const board=f.board.slice(-20);for(let y=0;y<20;y++)for(let x=0;x<10;x++){ctx.strokeStyle='#152131';ctx.strokeRect(x*52,y*52,52,52);if(board[y][x])cell(ctx,x*52,y*52,52,board[y][x])}
let ghost=shapes[f.current];if(ghost){ctx.globalAlpha=.25;for(const[x,y]of ghost)cell(ctx,(x+3)*52,y*52,52,'IJLOSTZ'.indexOf(f.current)+1);ctx.globalAlpha=1}
const hold=$('hold').getContext('2d'),next=$('next').getContext('2d');hold.clearRect(0,0,140,104);next.clearRect(0,0,140,600);mini(hold,f.held);f.queue.slice(0,5).forEach((p,i)=>mini(next,p,i*110));
$('lines').textContent=f.lines;$('pieces').textContent=f.pieces;$('efficiency').textContent=(f.lines/Math.max(1,f.pieces)).toFixed(2);let top=f.board.findIndex(row=>row.some(Boolean));$('height').textContent=top<0?0:f.board.length-top;$('position').textContent=`${index} / ${frames.length-1}`;$('scrub').value=index;$('keys').textContent=(f.keys||[]).join(' → ')||'Ready to begin.';$('status').textContent=index===frames.length-1?(data.topout?'Episode ended · topout':'Episode ended · piece limit'):f.clear?`${f.clear} line${f.clear>1?'s':''} cleared`:'Placement complete';
const g=$('graph').getContext('2d');g.clearRect(0,0,700,240);g.strokeStyle='#233044';g.beginPath();g.moveTo(0,220);g.lineTo(700,220);g.stroke();const max=Math.max(1,data.lines);g.strokeStyle='#56e1d8';g.lineWidth=3;g.beginPath();for(let i=0;i<=index;i++){const x=i/Math.max(1,frames.length-1)*690+5,y=215-frames[i].lines/max*200;i?g.lineTo(x,y):g.moveTo(x,y)}g.stroke();g.fillStyle='#56e1d8';g.beginPath();g.arc(index/Math.max(1,frames.length-1)*690+5,215-f.lines/max*200,5,0,Math.PI*2);g.fill();$('play').textContent=playing?'Pause':'Play'}
function step(delta){index=Math.max(0,Math.min(frames.length-1,index+delta));draw()}function toggle(){if(index===frames.length-1)index=0;playing=!playing;last=performance.now();draw()}
$('play').onclick=toggle;$('back').onclick=()=>{playing=false;step(-1)};$('forward').onclick=()=>{playing=false;step(1)};$('scrub').oninput=e=>{playing=false;index=Number(e.target.value);draw()};$('scrub').max=frames.length-1;$('policy').textContent=data.policy.toUpperCase()+' POLICY';$('seed').textContent='SEED '+data.seed;
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','BUTTON'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();toggle()}if(e.code==='ArrowLeft'){e.preventDefault();playing=false;step(-1)}if(e.code==='ArrowRight'){e.preventDefault();playing=false;step(1)}});
function animate(now){if(playing&&now-last>=Number($('speed').value)){last=now;step(1);if(index===frames.length-1){playing=false;draw()}}requestAnimationFrame(animate)}draw();requestAnimationFrame(animate);
</script></body></html>'''
